export async function listTools() {
  return [
    {
      name: 'lookup_invoice',
      description: 'Look up an invoice by its id.',
      inputSchema: {
        type: 'object',
        properties: {
          invoice_id: { type: 'string' }
        },
        required: ['invoice_id'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'lookup_invoice') {
    const err = new Error(`Unknown tool: ${name}`);
    err.code = 'UNKNOWN_TOOL';
    throw err;
  }

  const { invoice_id } = args;
  if (typeof invoice_id !== 'string' || invoice_id.length === 0) {
    const err = new Error('invoice_id is required and must be a non-empty string');
